record.field:
# Clear existing
env['bakery.production.list'].search([]).unlink()

if env.user.has_group('base.group_system'):
    domain = [('state', 'not in', ['done', 'cancel'])]
else:
    if not env.user.production_category_id:
        domain = [('id', '=', False)]
    else:
        domain = [
            ('state', 'not in', ['done', 'cancel']),
            ('product_id.categ_id', 'child_of', env.user.production_category_id.id),
            ('user_id', '=', env.user.id)
        ]

mos = env['mrp.production'].sudo().search(domain)

# Create lines
for mo in mos:
    env['bakery.production.list'].create({
        'mo_id': mo.id,
        'qty_producing': mo.qty_producing,
    })

# Return Action
action = {
    'type': 'ir.actions.act_window',
    'name': 'Produce All',
    'res_model': 'bakery.production.list',
    'view_mode': 'list',
    'view_id': env.ref('bakery_quick_production.view_bakery_production_list_tree').id,
    'target': 'current',
}
